const existingActions = $('Fetch Existing Actions').all().map(i => i.json);
const doneTypes = new Set(existingActions.filter(a => a.status === 'completed').map(a => a.action_type));
const attemptsByType = {};
for (const a of existingActions) { attemptsByType[a.action_type] = a.attempts; }
const nextAttempt = (type) => (attemptsByType[type] || 0) + 1;

const plan = $('Fetch Plan').first().json;
const incident = $('Fetch Incident').first().json;
const asset = $('Fetch Asset').first().json;
const approval = $('Fetch Approval').first().json;
const resourceRef = plan.resource_ref || {};

const isRepair = plan.plan_type === 'repair_via_technician';
const isReplace = plan.plan_type === 'replace_asset';
const isRelocate = plan.plan_type === 'relocate_operation';

const workOrderStatus = isRepair ? 'assigned' : 'open';
const assignedTechnicianId = isRepair ? resourceRef.technician_id : null;
const workOrderDescription = isRepair
  ? `Repair ${asset.name} (${asset.code}) - ${resourceRef.name} dispatched, ETA ${plan.estimated_recovery_minutes} min`
  : isReplace
  ? `Repair/inspect ${asset.name} (${asset.code}) - continuity restored via replacement (${resourceRef.name})`
  : `Repair/inspect ${asset.name} (${asset.code}) - operation relocated to ${resourceRef.name}`;

const slackText = isRepair
  ? `:wrench: *${asset.code} recovery* — Technician *${resourceRef.name}* dispatched, ETA ${plan.estimated_recovery_minutes} min. Incident ${incident.id}.`
  : isReplace
  ? `:package: *${asset.code} recovery* — Replacing with *${resourceRef.name}*, setup ${plan.estimated_recovery_minutes} min. Incident ${incident.id}.`
  : `:door: *${asset.code} recovery* — Operation relocated to *${resourceRef.name}*, transfer ${plan.estimated_recovery_minutes} min. Incident ${incident.id}.`;

const expectedActionTypes = ['work_order', 'slack_notify'];
if (isRelocate) expectedActionTypes.push('resource_reservation', 'calendar_update', 'gmail_notify');
if (isReplace) expectedActionTypes.push('inventory_decrement');

return [{
  json: {
    plan_type: plan.plan_type,
    plan_id: plan.id,
    incident_id: incident.id,
    asset_id: asset.id,
    asset_code: asset.code,
    asset_name: asset.name,
    resource_ref: resourceRef,
    estimated_recovery_minutes: plan.estimated_recovery_minutes,
    work_order_done: doneTypes.has('work_order'),
    slack_done: doneTypes.has('slack_notify'),
    calendar_done: doneTypes.has('calendar_update'),
    gmail_done: doneTypes.has('gmail_notify'),
    reservation_done: doneTypes.has('resource_reservation'),
    inventory_done: doneTypes.has('inventory_decrement'),
    work_order_status: workOrderStatus,
    assigned_technician_id: assignedTechnicianId,
    work_order_description: workOrderDescription,
    slack_text: slackText,
    location_id: isRelocate ? resourceRef.location_id : null,
    location_name: isRelocate ? resourceRef.name : null,
    inventory_id: isReplace ? resourceRef.inventory_id : null,
    expected_action_types: expectedActionTypes,
    work_order_attempt: nextAttempt('work_order'),
    slack_attempt: nextAttempt('slack_notify'),
    calendar_attempt: nextAttempt('calendar_update'),
    gmail_attempt: nextAttempt('gmail_notify'),
    reservation_attempt: nextAttempt('resource_reservation'),
    inventory_attempt: nextAttempt('inventory_decrement')
  }
}];

const finalActions = $('Fetch Final Actions').all().map(i => i.json);
const expected = $('Compute Execution Plan').first().json.expected_action_types;
const completedTypes = new Set(finalActions.filter(a => a.status === 'completed').map(a => a.action_type));
const failedTypes = finalActions.filter(a => a.status === 'failed').map(a => a.action_type);

let status;
if (expected.every(t => completedTypes.has(t))) {
  status = 'completed';
} else if (expected.some(t => completedTypes.has(t))) {
  status = 'partially_completed';
} else {
  status = 'failed';
}

return [{
  json: {
    status: status,
    completed_types: Array.from(completedTypes),
    failed_types: failedTypes,
    expected_types: expected
  }
}];
